CREATE TABLE Customers_Table (
    CustomerID INTEGER PRIMARY KEY,
    Name VARCHAR(255),
    Phone INTEGER
);

CREATE TABLE Airlines_Table (
    AirlineID INTEGER PRIMARY KEY,
    AirlineName VARCHAR(255),
    Route VARCHAR(255),
    Time DATETIME
);

CREATE TABLE CustomerReviews_Table (
    AirlineID INTEGER,
    CustomerID INTEGER,
    ReviewContent VARCHAR(255),
    ReviewGrade FLOAT,
    ReviewID INTEGER PRIMARY KEY
);

CREATE TABLE CustomerBankAccounts_Table (
    AccountID null PRIMARY KEY,
    AccountNumber null,
    Balance null,
    CustomerID null
);
